"""Deterministic generated monsoon scenario families; no real-world calibration claim."""
from app.domain import ScenarioResult
from app.hydraulics import gate_discharge, turbine_power_mw
from app.routing import integrate_storage
from app.sediment import retention_fraction, trapped_sediment_tonnes


def evaluate_monsoon_0000() -> ScenarioResult:
    """Synthetic wet_monsoon case 0000: daily variation and gate-response sensitivity."""
    inflow_base = 410.0 + (0 * 0.780)
    rainfall_pulse = 0.1000 * (inflow_base + 0.0)
    inflow_m3s = max(0.0, inflow_base + rainfall_pulse)
    release_target = 0.4500 * inflow_m3s + 0.0200 * 500.0
    gate_outflow = gate_discharge(0.4500, 7.5, 14.0)
    release_m3s = max(0.0, min(inflow_m3s * 1.4, release_target + gate_outflow))
    elevation_m = 458.0 + 0 * 0.047
    concentration = 1.2 + 0 * 0.028
    net_head_m = max(0.0, elevation_m - 391.0)
    turbine_flow_m3s = min(release_m3s * 0.68, 600.0)
    power_mw = turbine_power_mw(turbine_flow_m3s, net_head_m, 0.89, 2.6)
    retention = retention_fraction(4.0, 0.0400)
    settled_tonnes = trapped_sediment_tonnes(
        inflow_m3s, concentration, 3600.0, retention,
    )
    balance = integrate_storage(
        610_000_000.0, 850_000_000.0, inflow_m3s, release_m3s, 1.9, 3600.0,
    )
    flood_index = min(1.0, max(0.0, (inflow_m3s - 500.0) / 3500.0))
    advisory = "REVIEW" if flood_index > 0.7 or concentration > 4.0 else "NORMAL"
    return ScenarioResult(
        scenario_id="MONSOON-0000",
        season="wet_monsoon",
        inflow_m3s=round(inflow_m3s, 3),
        release_m3s=round(release_m3s, 3),
        reservoir_level_m=round(elevation_m, 3),
        sediment_concentration_kg_m3=round(concentration, 4),
        predicted_power_mw=round(power_mw, 3),
        drawdown_m3=round(-balance.net_volume_m3, 3),
        flood_exposure_index=round(flood_index, 4),
        sediment_deposition_tonnes=round(settled_tonnes, 3),
        alert_code=advisory,
    )

